  tr: {
    name: "Türkçe", code: "TR", html: "tr", day: "Günün Buketi #",
    t: {
      "nav.bouquets": "Buketler", "nav.features": "Özellikler", "nav.press": "Basın", "nav.wishlist": "İstek listesi",
      "hero.tagline": "Birinci şahıs, sıcacık bir çiçekçi oyunu.",
      "hero.sub": "Kendi çiçeklerini yetiştir, her buketi elinle sar ve seninle birlikte büyüyen küçük bir dükkân işlet.",
      "cta.wishlist": "Steam'de istek listene ekle", "cta.discord": "Discord'a katıl", "hero.status": "Geliştiriliyor · PC (Steam)",
      "play.eyebrow": "Çiçekçi tezgâhında", "play.title": "Yetiştir. Sar. Sat.",
      "play.body": "Her buket bahçendeki bir tohumla başlar. Çiçek açınca tezgâha getir, çiçekleri seç, kâğıdı kes, kurdeleyi bağla. Sonra rafa koy ve kimin geleceğini bekle.",
      "botd.eyebrow": "Günün Buketi", "botd.title": "Her gün yeni bir buket",
      "botd.lead": "Her gün oyunda yeni bir buket sarıp paylaşıyorum. Şimdiye kadarki koleksiyon burada.", "botd.follow": "Yenileri her gün burada:",
      "f1.title": "Buketini Kendin Hazırla", "f1.body": "Müşterinin isteğini dinle, çiçeklerini seç ve buketini kendi ellerinle hazırla. Son dokunuş her zaman senin.",
      "f2.title": "Çiçeklerini Yetiştir", "f2.body": "Tohumlarını ek, sula ve hasat et. Çiçeklerini dolaplara stokla. Dükkânın büyüdükçe yeni çiçeklerin kilidini aç.",
      "f3.title": "Raflarını Doldur", "f3.body": "Saksıları ve vazoları raflarına diz, dükkânını güne hazırla.",
      "f4.title": "Müşterilerini Ağırla", "f4.body": "Her müşterinin bir hikâyesi var: kimi sevdiğine, kimi doğum günü için çiçek ister. Onları dinle ve isteklerine en uygun buketi hazırla.",
      "f5.title": "Kargoları Hazırla", "f5.body": "İstersen internet üzerinden sipariş al, buketlerini paketle ve kargoyla gönder.",
      "f6.title": "Albüm Defterini Tamamla", "f6.body": "Hazırladığın buketlerin fotoğrafını çek ve albüm defterine ekle. Tarif sayfalarını doldur, en sevdiğin kareleri sakla.",
      "x1.title": "Yardımcı Tut", "x1.body": "Kasada beklemekten sıkılırsan bir çalışan işe al. O satışlarla ilgilensin, sen de buketlerine daha çok vakit ayır.",
      "x2.title": "Arkadaşlarınla Oyna (yakında)", "x2.body": "İster tek başına, ister 4 kişiye kadar arkadaşınla birlikte oyna. Dükkânı beraber işletin ve birlikte büyütün.",
      "x3.title": "Kendi Temponda Oyna", "x3.a": "Dükkânını hangi gün açacağına sen karar ver",
      "x3.b": "İstersen sadece buket yap, istersen dükkân işlet", "x3.c": "Süre baskısı ve ceza yok",
      "band.title": "İstek listesi düşündüğünden çok daha fazla yardım eder",
      "band.body": "Tek kişinin yaptığı bir oyun için her istek listesi çok değerli. Panda Flora'yı Steam'de istek listene ekle, çıktığı gün haberin olsun.",
      "dev.title": "Tek kişi yapıyor",
      "dev.body": "Panda Flora'yı tek bir geliştirici, çiçek çiçek yapıyor. Geliştirme notları, ilk görüntüler ve günün buketi önce Discord'a geliyor.",
      "dev.link": "Discord'a gel, merhaba de", "foot.press": "Basın kiti", "sc.release": "Çıkış: 2027",
      "feat.label": "Yer aldığı yerler", "feat.automaton": "Japonya · Ekim 2026", "feat.gamebase": "Tayvan · Ekim 2026"
    }
  },
